def check_small_n(n_list):
    results = []
    for n in n_list:
        best_c = -1
        best_m = -1
        m_start = int((2*n)**0.5)
        for m in range(max(2, m_start - 2), m_start + 10):
            if m * (m - 1) // 2 < n:
                continue
            q = (2 * n) // m
            r = (2 * n) % m
            if r == 0:
                d1, d0, n1, n0 = q, q, m, 0
            else:
                d1, d0, n1, n0 = q + 1, q, r, m - r
            max_k = -1
            for k in range(n1 * (n1 - 1) // 2 + 1):
                e10 = n1 * d1 - 2 * k
                if e10 < 0 or e10 > n1 * n0: continue
                num_e00 = n0 * d0 - e10
                if num_e00 < 0 or num_e00 % 2 != 0: continue
                e00 = num_e00 // 2
                if e00 > n0 * (n0 - 1) // 2: continue
                if k + e10 + e00 == n:
                    max_k = max(max_k, k)
            if max_k != -1:
                c = max_k * d1 + (n - max_k) * d0
                if c > best_c:
                    best_c = c
                    best_m = m
        results.append((n, best_c, best_m))
    return results

