        if left > right:
            return False
    return True

def solve_for_n(n):
    best_cost = 0
    for k in range(2, 2*n + 1):
        if k*(k-1)//2 < n:
            continue
        avg = 2*n // k
        rem = (2*n) % k
        degrees = [avg+1]*rem + [avg]*(k-rem)
        degrees.sort(reverse=True)
        if is_graphical(degrees):
            x = [0] * k
            for j in range(k):
                x[j] = min(degrees[j], j)
            total_x = sum(x)
            if total_x < n:
                continue
            diff = total_x - n
            for j in range(k-1, -1, -1):
                reduction = min(diff, x[j] - max(0, degrees[j] - (k-1-j)))
                x[j] -= reduction
                diff -= reduction
            if diff == 0:
                cost = sum(degrees[j] * x[j] for j in range(k))
                if cost > best_cost:
                    best_cost = cost
    return best_cost

