def solve_n_final(n):
    N = 2
    while N * (N - 1) // 2 < n:
        N += 1

    d_high = (2 * n + N - 1) // N
    d_low = (2 * n) // N

    if d_high == d_low:
        x, y = N, 0
    else:
        x = (2 * n - N * d_low) // (d_high - d_low)
        y = N - x

    best_c = 0
    for e_hh in range(x * (x - 1) // 2 + 1):
        e_hl = x * d_high - 2 * e_hh
        e_ll = n - x * d_high + e_hh

        if e_hl >= 0 and e_hl <= x * y and e_ll >= 0 and e_ll <= y * (y - 1) // 2 and e_hl <= y * d_low:
            if 2 * e_hh + e_hl == x * d_high and e_hl + 2 * e_ll == y * d_low:
                best_c = max(best_c, (d_high - d_low) * e_hh + d_low * n)

    return best_c

