def solve_small_with_k_plus_r(n):
    best_C = 0
    # Try K_k with r edges added to a new vertex
    for k in range(2, n + 2):
        m_k = k * (k - 1) // 2
        r = n - m_k
        if 0 <= r < k:
            # K_k plus r edges to a new vertex v_k+1
            # The r edges are (v_k+1, v_1), ..., (v_k+1, v_r)
            # Degrees:
            # d_1...d_r = (k-1) + 1 = k
            # d_{r+1}...d_k = k-1
            # d_{k+1} = r
            # Edges:
            # K_k (k(k-1)/2 edges)
            # r edges from v_{k+1} to v_1...v_r
            edges = list(itertools.combinations(range(k), 2))
            for i in range(r):
                edges.append((k, i))

            C = get_C_for_graph(edges)
            if C > best_C:
                best_C = C
    return best_C

# Let's test n=1 to 10 for both K_k - r and K_k + r
def best_C_complete_minus_r(n):
    best_C = 0
    for k in range(2, n + 2):
        m_k = k * (k - 1) // 2
        r = m_k - n
        if 0 <= r < m_k:
            if r <= k - 1:
                degrees = [0] * k
                for i in range(k):
                    degrees[i] = k - 1
                for i in range(r):
                    degrees[0] -= 1
                    degrees[i+1] -= 1
                edges = list(itertools.combinations(range(k), 2))
                to_remove = [(0, i+1) for i in range(r)]
                edges_to_keep = [e for e in edges if e not in to_remove]

                degrees_final = [0] * k
                for u, v in edges_to_keep:
                    degrees_final[u] += 1
                    degrees_final[v] += 1
                C = 0
                for u, v in edges_to_keep:
                    C += min(degrees_final[u], degrees_final[v])
                if C > best_C:
                    best_C = C
    return best_C

